insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('94dc8915-cb40-4e78-949a-a58da60f63cb', 'QuintoAndar', 'https://www.quintoandar.com.br', 'Mercado imobiliário', 'São Paulo , São Paulo , Brasil', 'QuintoAndar é uma startup brasileira que usa tecnologia para simplificar processos de aluguel e compra e venda  de imóveis . Foi fundada no início de 2013  e está presente em mais de 70 cidades brasileiras. Na modalidade aluguel, a companhia administra o pagamento ao proprietário, dispensando o inquilino de apresentar fiador , seguro-fiança ou depósito caução .', 2013);
