('f8e10295-c24a-4232-b981-26d65052435c', 'noticia', 'Méliuz (verbete)', 'Méliuz é uma startup brasileira , criada em 2011 ,   que disponibiliza cupons de desconto de lojas online e devolve ao consumidor um percentual do valor pago pelo produto ( cashback ).', 'https://pt.wikipedia.org/wiki/Méliuz'),
('f8e10295-c24a-4232-b981-26d65052435c', 'site_institucional', 'Cupons de Desconto, Ofertas e Cashback | Méliuz', 'Cupons de Desconto, Ofertas e Cashback | Méliuz Pular para o conteúdo Méliuz Para empresas Cupons Lojas Login Cadastrar Méliuz Entrar Cupom de desconto e cashback em centenas de lojas online Ative o cashback direto no site da loja e teste os cupons disponíveis automaticamente. E o melhor, é gratuito! Cadastre-se grátis! Ou baixe o app do Méliuz e comece a ganhar cashback em suas lojas favoritas. Baixar o aplicativo Mais de 50 milhões de pessoas já usam o Méliuz para ganhar cashback em suas compras + 800 lojas parceiras Melhores Cupons de Desconto Ver todos Cupom Petz exclusivo de 10% de desconto em todo site + 2% cashback Pegar cupom Ver mais cupons Cupom Netshoes exclusivo com desconto de 10% + 3% cashback Pegar cupom Ver mais cupons Use cupom de desconto Dafiti e receba R$30 de economia + 1% cashback Pegar cupom Ver mais cupons Cupom Beleza na Web exclusivo com 10% OFF no site todo + até 15% cashback era 3% Pegar cupom Ver mais cupons Cupom Dell com 10% de desconto garantido em suas compras + até 3% cashback era 1% Pegar cupom Ver mais cupons Use cupom Leroy Merlin e economize 10% + 1,5% cashback Pegar cupom Ver mais cupons 15% OFF aplicando cupom de desconto Magazine Luiza + até 10% cashback era 2% Pegar cupom Ver mais cupons Melhores Lojas de Cupons e Cashback Amazon Magazine Luiza Shopee Casas Bahia AliExpress Netshoes KaBuM Drogasil Renner Centauro Drogaria São Paulo Carrefour Shein Droga Raia Booking Pague Menos Leroy Merlin Nike Natura Cobasi Samsung Petz Americanas Hoteis.com Época Cosméticos MadeiraMadeira Electrolux Adidas Dell O Boticário Fast Shop Uber Mercado Livre iFood Zé Delivery Melhores Categorias de Cupons e Cashback Ver todas Celulares e Smartphones Viagem e Turismo Farmácia Departamentos Livros Moda e Acessórios Eletrodomésticos Pet Shop Informátic', 'https://www.meliuz.com.br'),
('f8e10295-c24a-4232-b981-26d65052435c', 'blog', 'Méliuz - Dicas de compras, cupons de desconto, cashback e mais', 'Méliuz - Dicas de compras, cupons de desconto, cashback e mais Amazon Prime Day 2024: data, como participar e muito mais Saiba tudo sobre a data e descubra como economizar muito nas suas compras. Acesse e confira Produtos mais vendidos no Mercado Livre em 2024: top 10 Confira com a gente quais são os produtos que fazem mais sucesso entre os consumidores no Mercado Livre. Acesse e confira Presentes para o pai: presentes para surpreender no Dia dos Pais Confira com a gente algumas das melhores opções de presentes para o Dia dos Pais! Acesse e Confira Novo Cartão Méliuz Indique e Ganhe Como funciona Gift Card , Shopping O que é Gift Card? Saiba para que serve o Cartão Presente e como usar 28/08/2026 / Leia mais Você pode gostar Gift Card Uber, cupom de desconto e cashback para você economizar no app 09/02/2021 Cashback iFood: economize na compra do seu iFood Card com o Méliuz 24/03/2021 Airbnb: guia completo para se hospedar com economia 22/11/2022 Presentes , Variedades 15 dicas de presente de aniversário para mãe 27/08/2026 / Leia mais Você pode gostar Presentes Dia das Mães: aqui você encontra todas as dicas para arrasar e emocionar o coração da sua mãe 07/04/2022 Ovos de Páscoa 2023: Onde comprar com melhores preços 06/04/2023 Presentes de Natal: melhores dicas para presentear na data 13/12/2023 Finanças Aplicativos para ganhar dinheiro: conheça os 50 melhores 27/08/2026 / Leia mais Você pode gostar As gírias do mundo cripto: entenda os termos do Criptonário 27/07/2022 Empréstimo online: o que é e quais são as suas vantagens? 23/05/2022 Cartão de crédito: como fazer online, quais os melhores cartões sem anuidade e muito mais 10/08/2022 Presentes , Shopping Presente para a sogra: 20 dicas para surpreendê-la! 27/08/2026 / Leia mais Você pode gostar Presente de Páscoa par', 'https://www.meliuz.com.br/blog/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('ff96b54b-3541-4ec8-be5b-3248056d7718', 'Hotmart', 'https://www.hotmart.com', 'Comércio eletrônico', 'Amesterdã , Holanda', 'Hotmart é uma plataforma digital fundada em 2011 pelos brasileiros João Pedro Resende e Mateus Bicalho. O modelo de negócios da Hotmart é baseado na venda e distribuição de produtos digitais, operando como uma rede de afiliados. Com uma base de usuários que ultrapassou 26 milhões em 2021,   a plataforma oferece uma variedade de conteúdos digitais, incluindo audiolivros , cursos online , podcasts  ', 2011);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('ff96b54b-3541-4ec8-be5b-3248056d7718', 'noticia', 'Hotmart (verbete)', 'Hotmart é uma plataforma digital fundada em 2011 pelos brasileiros João Pedro Resende e Mateus Bicalho. O modelo de negócios da Hotmart é baseado na venda e distribuição de produtos digitais, operando como uma rede de afiliados. Com uma base de usuários que ultrapassou 26 milhões em 2021,   a plataforma oferece uma variedade de conteúdos digitais, incluindo audiolivros , cursos online , podcasts  e livros eletrônicos .', 'https://pt.wikipedia.org/wiki/Hotmart'),
('ff96b54b-3541-4ec8-be5b-3248056d7718', 'site_institucional', 'Hotmart: a maior plataforma de curso online do mundo', 'Hotmart: a maior plataforma de curso online do mundo FAZ MAIS DE R$ 10 MIL/MÊS NO DIGITAL? Liberamos um diagnóstico rápido e gratuito para você vender mais! QUERO MEU DIAGNÓSTICO FAZ MAIS DE R$ 10 MIL/MÊS NO DIGITAL? Liberamos um diagnóstico rápido e gratuito para você vender mais! QUERO MEU DIAGNÓSTICO FAZ MAIS DE R$ 10 MIL/MÊS NO DIGITAL? Liberamos um diagnóstico rápido e gratuito para você vender mais! QUERO MEU DIAGNÓSTICO FAZ MAIS DE R$ 10 MIL/MÊS NO DIGITAL? Liberamos um diagnóstico rápido e gratuito para você vender mais! QUERO MEU DIAGNÓSTICO Comece gratuitamente Acessar minhas compras Gerenciar meus negócios Entrar Comece gratuitamente Aqui o seu negócio digital acontece! Crie, gerencie e venda seu produto digital para o mundo todo com o ecossistema mais completo do mercado. Cadastre-se agora Seguro e confiável 4.9 Baseado em +350.000 avaliações Crie sua conta agora. É gratuito Crie sua conta agora. É gratuito Crie seu produto digital em poucos passos. 1 . Crie sua conta É grátis e leva menos de 5 minutos. Basta seguir o passo a passo na plataforma, sem burocracia e sem perder tempo. 2 . Configure seu infoproduto Crie seu curso online, mentoria, ebook e diversas outras soluções avançadas em uma plataforma completa e intuitiva. 3 . Comece a vender Lance seu produto com página de vendas, checkout completo e ferramentas poderosas para alcançar resultados de múltiplos dígitos. Comece agora A Hotmart aposta em você desde o começo Fature R$ 10 mil em até 30 dias após sua primeira venda e desbloqueie: Reunião estratégica com especialista Atendimento por WhatsApp R$ 1 mil em ferramentas Eligibilidade a gerente de contas e taxa reduzida Quero participar Quero participar Entre agora para a maior plataforma de produtos digitais do mundo. +50 Bilhões de reais em vendas de ', 'https://www.hotmart.com'),
('ff96b54b-3541-4ec8-be5b-3248056d7718', 'blog', 'Blog Hotmart - Criação de conteúdo e empreendedorismo', 'Blog Hotmart - Criação de conteúdo e empreendedorismo Se você já vende mais de R$10mil por mês com produtos digitais, venha faturar ainda mais com a Hotmart. Se você já vende mais de R$10mil por mês com produtos digitais, venha faturar ainda mais com a Hotmart. Falar com especialista Falar com especialista Buscar pt-br Português - Brasil English Español Cadastre-se grátis Cadastre-se grátis Aprenda como fazer um ebook para vender pela internet Confira um passo a passo para começar no mercado digital O que é Hotmart e como funciona? DESCUBRA TUDO! A maior comunidade do digital Conteúdo rico, boas conversas e histórias inspiradoras. Falta só você aqui! 18/08/2026 • Empreendedorismo digital Como vender produtos digitais na Hotmart: passo a passo completo Quer vender produtos digitais? Entenda como começar do zero, quais formatos escolher e como estruturar, divulgar e comercializar seu produto pela internet. Entre para a economia criativa Saiba quais são os primeiros passos para a criação de conteúdo e o empreendedorismo digital. Para Produtores Para Afiliados 1 Se você não sabe por onde começar Escolha um nicho. A partir dele, você faz a pesquisa de mercado e se aprofunda nas possibilidades. 2 Saiba quem vai se beneficiar do seu conteúdo Desenhe a buyer persona, uma representação do seu público. Descubra como! 3 Estabeleça o formato do seu infoproduto Identifique a melhor maneira de transmitir o seu conteúdo ao seu público. Conheça as possibilidades! 4 Tenha uma estratégia Saiba como gerar autoridade, conquistar audiência e compradores. Aprenda como ser um Produtor de conteúdo 1 Entenda o que é um programa de Afiliados Quem começa do zero tem como primeira missão entender o que é e como funciona essa área! 2 Escolha o seu nicho Defina um nicho de atuação para melhorar aind', 'https://hotmart.com/pt-br/blog');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('e9534759-6e9a-4e31-9dce-b2ffd7203f1f', 'Sympla', 'https://sympla.com.br', 'Tecnologia', 'Belo Horizonte , MG', 'Sympla é uma startup brasileira de tecnologia fundada em 2011,  atuante no ramo de venda de tickets e gestão de eventos na internet , sendo líder no setor no Brasil.', 2011);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('e9534759-6e9a-4e31-9dce-b2ffd7203f1f', 'noticia', 'Sympla (verbete)', 'Sympla é uma startup brasileira de tecnologia fundada em 2011,  atuante no ramo de venda de tickets e gestão de eventos na internet , sendo líder no setor no Brasil.', 'https://pt.wikipedia.org/wiki/Sympla'),
('e9534759-6e9a-4e31-9dce-b2ffd7203f1f', 'site_institucional', 'Sympla - Ingressos para Eventos, Teatros, Shows, Cursos e mais', 'Sympla - Ingressos para Eventos, Teatros, Shows, Cursos e mais para Produtores Crie eventos, divulgue e venda ingressos com facilidade Da publicação à venda: suporte em todas as etapas. Publicação grátis: sem taxa de adesão ou mensalidade. Crie seu evento Veja como funciona Precisa de ajuda? Tire suas dúvidas aqui Como eu cancelo ou peço reembolso de ingressos? Como localizar meus ingressos? Como trocar a titularidade do ingresso? Como acesso meu certificado? Não consigo acessar minha conta, o que fazer? Explore nossas coleções Ver tudo Eventos mais comprados nas últimas 24h Ver tudo', 'https://sympla.com.br'),
('e9534759-6e9a-4e31-9dce-b2ffd7203f1f', 'noticia', 'Imprensa', 'Imprensa Imprensa Muito mais que uma plataforma A Sympla está no site, no app, nas mídias sociais, nos meios de comunicação e em todo lugar! Entre em contato ou acesse nossos materiais exclusivos para a imprensa. Para obter mais informações sobre a Sympla, solicitação de pauta ou outras demandas, entre em contato por email. [email protected] Logos e Guia da Marca Baixar arquivos Material Fotográfico Baixar arquivos Acompanhe nossos canais Já são milhares de pessoas acompanhando tudo sobre o universo dos eventos e conteúdos nos nossos canais. Para ficar por dentro, acesse: Estratégias e dicas valiosas para ter sucesso na produção e gestão de eventos e conteúdos Entretenimento, aprendizado, comportamento e os principais assuntos do momento Conheça tudo o que a Sympla pode oferecer, além das melhores experiências que estão rolando no país INSTAGRAM Fique por dentro dos bastidores da Sympla, nossa cultura, vagas, além de conteúdos exclusivos para produtores de eventos e conteúdos LINKEDIN Vídeos explicativos e tutoriais essenciais para produtores de eventos e conteúdos YOUTUBE Espaço para diálogos em tempo real e conferir as últimas novidades da Sympla e do mundo dos eventos TWITTER Dúvidas? Acesse a nossa Central de ajuda .', 'https://www.sympla.com.br/imprensa');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('35670ebd-62c3-4108-9835-1b481456778e', 'Conta Azul', 'https://contaazul.com', 'Software', 'Joinville , SC , Brasil', 'Conta Azul é uma empresa brasileira de software fundada em 2012, com sede em Joinville (Santa Catarina), voltada a micro, pequenas e médias empresas. Desenvolve um sistema de gestão empresarial (ERP) em nuvem, no modelo SaaS (software como serviço), que inclui funcionalidades como controle financeiro, vendas, estoque e emissão de documentos fiscais, além de integração com contadores e empresas de ', 2012);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('35670ebd-62c3-4108-9835-1b481456778e', 'noticia', 'Conta Azul (verbete)', 'Conta Azul é uma empresa brasileira de software fundada em 2012, com sede em Joinville (Santa Catarina), voltada a micro, pequenas e médias empresas. Desenvolve um sistema de gestão empresarial (ERP) em nuvem, no modelo SaaS (software como serviço), que inclui funcionalidades como controle financeiro, vendas, estoque e emissão de documentos fiscais, além de integração com contadores e empresas de BPO financeiro. Desde 2025, integra o grupo Visma  , conglomerado norueguês de software empresarial.', 'https://pt.wikipedia.org/wiki/ContaAzul'),
('35670ebd-62c3-4108-9835-1b481456778e', 'site_institucional', 'Sistema ERP de Controle Financeiro Empresarial - Conta Azul', 'Sistema ERP de Controle Financeiro Empresarial - Conta Azul Entrar Teste Grátis Advocacia Advogados autônomos e escritórios de advocacia. Consultoria Escritórios e profissionais autônomos. Educação Empresas de cursos, treinamentos, escolas de ensino e afins. Elétricas & Hidráulicas Empresas elétricas, hidráulicas, gás e ventilação. Engenharia Escritórios de engenharia, construção civil, construtoras e afins. Manutenções Empresas de manutenção, instalação de máquinas e equipamentos. Marketing Agências de marketing, publicidade ou propaganda. Saúde Clínica de saúde, fisioterapia, nutrição ou odontologia. Seguros Corretoras seguros, planos de saúde e previdência. Tecnologia Startups, empresas de software e afins. Terceiro Setor Ongs, associações e entidades sem fim lucrativo. Encontre um Contador Contadores e BPOs certificados para ajudar a sua empresa. Emissor para Afiliados Shopee Emita suas notas fiscais em lote a partir do relatório de comissões da Shopee. Gestão Financeira Acompanhe entradas e saídas em um só lugar. Conciliação Bancária Concilie o financeiro de todas suas contas automaticamente. Relatórios Acompanhe resultados com dados sempre atualizados. Cobrança Automática Deixe as cobranças no automático e evite atrasos. Conta PJ Abra e gerencie a conta da sua empresa sem burocracia. Vendas & Clientes Controle vendas, clientes e recebimentos em um só lugar. Contratos Recorrentes Gerencie as vendas recorrentes e fuja da inadimplência. Nota Fiscal Emita NF-e, NFS-e NFC-e sem esforços. Compras & Fornecedores Controle total das compras e fornecedores em um só lugar. Estoque & Produtos Controle o estoque e evite faltas ou excessos. Integrações Temos + de 100 opções de integrações disponíveis. Conta Azul IA Capture notas e lance contas com a ajuda da IA. CA de Bolso Ger', 'https://contaazul.com'),
('35670ebd-62c3-4108-9835-1b481456778e', 'blog', 'Dicas de Gestão, Contabilidade E Negócios - Blog Conta Azul', 'Dicas de Gestão, Contabilidade E Negócios - Blog Conta Azul Dicas de gestão financeira, contabilidade e empreendedorismo para pequenas e médias empresas | Blog Conta Azul Notícias Grupo Visma adquire Dootax e Pag Útil e cria a primeira plataforma de automação tributária integrada do Brasil Equipe Conta Azul Conta Azul Como a Conta Azul ajudou a Aclima a faturar 300% mais Equipe Conta Azul Novidades Conta Azul passa a integrar o grupo Visma Equipe Conta Azul Posts em destaque Contabilidade e Impostos Tudo o que você precisa saber sobre Nota Fiscal Eletrônica Equipe Conta Azul 03/07/2025 Gestão Financeira 7 exemplos de mensagem de cobrança para clientes para enviar no WhatsApp Equipe Conta Azul 03/06/2025 Gestão de Pessoas 10 modelos de comunicado interno para usar na sua empresa Equipe Conta Azul 03/08/2026 Gestão Financeira O que é DRE: para que serve, estrutura, como fazer e planilha grátis Equipe Conta Azul 02/07/2026 Últimos posts Vendas Como vender na Shopee? Guia completo para iniciantes e empreendedores Equipe Conta Azul 01/09/2026 Gestão de Negócios Blueprint: o que é, para que serve e como aplicar no seu negócio Equipe Conta Azul 31/08/2026 Contabilidade e Impostos DBE: o que é, função, quando é necessário e como emitir em 2026 Equipe Conta Azul 28/08/2026 Vendas Recibo online e gratuito: veja o que é, como elaborar e baixe o modelo Equipe Conta Azul 27/08/2026 Contabilidade e Impostos PGDAS-D: o que é, como emitir, declarar e pagar no Simples Nacional Equipe Conta Azul 24/08/2026 Gestão de Negócios Emitir nota fiscal MEI: guia completo com tudo que vocês precisa saber Equipe Conta Azul 20/08/2026 Gestão de Negócios CNPJ: o que é e como abrir o seu Cadastro Nacional da Pessoa Jurídica Equipe Conta Azul 19/08/2026 E-commerce Logística reversa: entenda o que é, ti', 'https://contaazul.com/blog/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('e27ad557-77aa-4691-a603-96c50a331c6f', 'Wildlife Studios', 'https://wildlifestudios.com/pt-br/', 'Jogos eletrônicos (Mobile)', 'São Paulo , Brasil', 'Wildlife Studios é uma desenvolvedora brasileira de jogos eletrônicos e publicadora para dispositivos móveis , fundada em 4 de abril de 2011 por Victor Lazarte, Arthur Lazarte e Michael Mac-Vicar. A empresa é reconhecida como uma das maiores do mundo em seu segmento, com mais de 60 jogos lançados e bilhões de downloads globalmente.', 2011);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('e27ad557-77aa-4691-a603-96c50a331c6f', 'noticia', 'Wildlife Studios (verbete)', 'Wildlife Studios é uma desenvolvedora brasileira de jogos eletrônicos e publicadora para dispositivos móveis , fundada em 4 de abril de 2011 por Victor Lazarte, Arthur Lazarte e Michael Mac-Vicar. A empresa é reconhecida como uma das maiores do mundo em seu segmento, com mais de 60 jogos lançados e bilhões de downloads globalmente.', 'https://pt.wikipedia.org/wiki/Wildlife_Studios'),
('e27ad557-77aa-4691-a603-96c50a331c6f', 'site_institucional', 'Wildlife', 'Wildlife English Jogos Publishing Sala de Imprensa Carreiras Estágio Quem Somos O que você está procurando? Todo dia é dia de jogar Tennis Clash! Conheça Tennis Clash Battle Royale encontra MOBA. Jogue Zooba! Conheça Zooba Desperte seu potencial e trabalhe com games Ir para Carreiras Jogos Criamos jogos que vão marcar gerações! Veja nossos jogos Tennis Clash Zooba Sky Warriors Sniper 3D War Machines Tennis Clash Zooba Sky Warriors Sniper 3D War Machines Midas Merge Secret Puzzle Society Quem Somos A Wildlife Studios é uma das 10 maiores empresas de jogos para dispositivos móveis do mundo. Fundado no Brasil em 2011, nosso estúdio cresceu e se tornou uma organização verdadeiramente global. Temos escritórios nos Estados Unidos, Brasil e Finlândia – e ainda estamos expandindo. Hoje, nosso portfólio de mais de 60 jogos diverte bilhões de jogadores em todo o mundo. 400 Colaboradores 4.7 bi Downloads 60 Games 3 Escritórios Notícias CONFIRA NOSSAS ÚLTIMAS NOTÍCIAS Sala de Imprensa Não perca as notícias da Wildlife! Assine a nossa newsletter. E-mail ok I have read and accepted the Leia os Privacy Policy .', 'https://wildlifestudios.com/pt-br/'),
('e27ad557-77aa-4691-a603-96c50a331c6f', 'vaga', 'Carreiras |  Wildlife', 'Carreiras |  Wildlife English Jogos Publishing Sala de Imprensa Carreiras Estágio Quem Somos O que você está procurando? Are you ready to join this journey? Temos 20 vagas abertas, junte-se a nós. Buscar Life Is Wild Estar na Wildlife é fazer parte de algo grandioso! Nosso time é formado por pessoas excepcionais, dedicadas a criar coisas incríveis. Nos ajude a construir a melhor empresa de games para se trabalhar no mundo. Título Escritório Todos os Escritórios Categoria Todas as categorias Time Todos os Times Título Escritório Categoria Time Não foram encontradas vagas para essa pesquisa. Por favor, busque por outras especificações ou você pode ver todas as nossas vagas em aberto . TALENT ACQUISITION Finding the talent: how we recruit future Wilders for our teams Know More Faça parte da nossa rede de talentos e receba as nossas últimas notícias. E-mail ok I have read and accepted the Leia os Privacy Policy .', 'https://careers.wildlifestudios.com/pt-br/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('9f06909f-9b81-4e46-a9fa-806449b66a6f', 'Stone (fintech)', 'https://www.stone.com.br', 'Serviços Financeiros', 'Rio de Janeiro , Brasil', 'Stone é uma fintech brasileira que oferece soluções financeiras,  completas para empreendedores de todos os portes. Muito além da maquininha, a empresa atua com serviços de adquirência para diferentes formas de venda e também disponibiliza soluções bancárias, como Conta PJ e crédito, para ajudar a crescer e investir no seu negócio. Atua no mercado desde 2014, cobrindo todo o território brasileiro.', 2012);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('9f06909f-9b81-4e46-a9fa-806449b66a6f', 'noticia', 'Stone (fintech) (verbete)', 'Stone é uma fintech brasileira que oferece soluções financeiras,  completas para empreendedores de todos os portes. Muito além da maquininha, a empresa atua com serviços de adquirência para diferentes formas de venda e também disponibiliza soluções bancárias, como Conta PJ e crédito, para ajudar a crescer e investir no seu negócio. Atua no mercado desde 2014, cobrindo todo o território brasileiro. Em 2018 realizou sua oferta inicial de ações (IPO) na bolsa de valores de Nova Iorque ( NASDAQ ).  A Stone é parte integrante da holding Stone Co., que possui outras empresas do ecossistema de pagamentos no Brasil .', 'https://pt.wikipedia.org/wiki/Stone_Pagamentos'),
('9f06909f-9b81-4e46-a9fa-806449b66a6f', 'site_institucional', 'Stone: O Banco pra Quem Empreende | Stone', 'Stone: O Banco pra Quem Empreende | Stone Adquira Agora STONE PRA QUEM EMPREENDE Todos os jeitos de vender, crédito, controle do caixa e dos funcionários em um único banco Seja Stone Veja o que a Stone preparou pro seu negócio O BANCO DO SEU NEGÓCIO Link de pagamento Pix Catálogo Online Maquininha Link de pagamento Pix Catálogo Online Maquininha Reserva Stone Limite da Conta Capital de Giro Reserva Stone Limite da Conta Capital de Giro Conta PJ Stone Cartão Stone Maquininha Pix Conta PJ Stone Cartão Stone Maquininha Pix Investimentos Gestão de ponto Gestão de equipe Minhas Finanças Investimentos Gestão de ponto Gestão de equipe Minhas Finanças VENDAS CRÉDITO GESTÃO FINANCEIRA INTEGRAÇÕES Todos os jeitos de receber, pra você não deixar nenhuma venda escapar, seja no balcão, à distância, no e-commerce ou delivery Maquininha de cartão Maquininha no celular Pix na maquininha Link de pagamento Vendas online Catálogo Cartão de crédito Capital de giro Pix e Boleto no Crédito FGI PEAC Limite de conta Reserva Conta PJ Minhas finanças Gestão de funcionários Seguros Raio X Investimentos Integração com PDV Integração e-commerce Integração com ERP Integração marketplace VENDAS CRÉDITO GESTÃO FINANCEIRA INTEGRAÇÕES Todos os jeitos de receber, pra você não deixar nenhuma venda escapar, seja no balcão, à distância, no e-commerce ou delivery Maquininha de cartão Maquininha no celular Pix na maquininha Link de pagamento Vendas online Catálogo Cartão de crédito Capital de giro Pix e Boleto no Crédito FGI PEAC Limite de conta Reserva Conta PJ Minhas finanças Gestão de funcionários Seguros Raio X Investimentos Integração com PDV Integração e-commerce Integração com ERP Integração marketplace ESCOLHA O MELHOR PARA SUA EMPRESA Temos as melhores condições para o seu negócio! Como você quer ven', 'https://www.stone.com.br'),
('9f06909f-9b81-4e46-a9fa-806449b66a6f', 'noticia', 'Após seis anos da fundação, Stone Pagamentos fará IPO na Nasdaq – Money Times', 'Após seis anos da fundação, Stone Pagamentos fará IPO na Nasdaq – Money Times Money Times Crypto Times Agro Times Ibovespa Giro do Mercado Newsletters Money Trader Anuncie Últimas Notícias Newsletters Cotações Comprar ou vender? Carteiras Recomendadas Central de Dividendos Central de Fundos Imobiliários Central dos IPOs Renda Fixa Finanças Pessoais Mercados Economia Empresas Brasil Política Colunas Especiais Internacional Marketing Tecnologia Conteúdo de Marca Sobre Expediente Contato TEMPO REAL ver mais 11:51 Tribunal do Cade aprova compra de participação na CRDC pela B3 (B3SA3) sob condições 11:50 Safra corta preços-alvo de 9 ações, rebaixa RAIL3, MOTV3 e HBSA3 e define top picks 11:48 >> Ibovespa bate máxima aos 185.224,90 pontos, com alta de 3,06% IBOVESPA +0.00% 0 pts DOLAR +0.00% R$ 0.00 EURO +0.00% R$ 0.00 ver mais Tempo Real Cotações IPO Após seis anos da fundação, Stone Pagamentos fará IPO na Nasdaq Por Equipe Money Times 02 out 2018, 8:39 Siga no Youtube CONTINUA DEPOIS DA PUBLICIDADE CONTINUA DEPOIS DA PUBLICIDADE A Stone pediu ontem (1º) registro para IPO na bolsa de valores americana Nasdaq. A abertura de capital da empresa de pagamentos deve aumentar a pressão sobre suas concorrentes Cielo ( CIEL3 ) e PagSeguro. Veja o documento aqui . Esta última, inclusive, levantou US$ 2,3 bilhões em uma oferta inicial de ações realizada na Bolsa de Nova York em janeiro deste ano. Segundo o prospecto preliminar da oferta, Itaú BBA , Credit Suisse, Morgan Stanley, Bank of America Merrill Lynch, Goldman Sachs, JPMorgan, Citigroup e BTG Pactual vão coordenar a operação, que envolve ofertas primárias (papéis novos) e secundárias (ações detidas por atuais sócios). Segundo a empresa, a abertura de capital deve servir para para financiar futuras fusões, aquisições ou investime', 'https://www.moneytimes.com.br/apos-seis-anos-da-fundacao-stone-pagamentos-pede-ipo-na-nasdaq/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('734dd033-1cc6-456d-8463-56eab8fea100', 'PagBank', 'https://pagbank.com.br', 'Serviços financeiros', 'São Paulo , Brasil (sede operacional) Grande Caimão , Ilhas Cayman (domicílio legal)', 'PagBank (antigo PagSeguro ) é uma instituição bancária brasileira que atua como meio de pagamento eletrônico  sendo uma das responsáveis pela captura, transmissão e liquidação financeira de transações com cartões de crédito e débito, tanto no meio físico (com suas máquinas sem aluguel), quanto no meio eletrônico (com suas soluções de pagamento on-line),  sendo o braço mais rentável do grupo UOL .', 2006);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('734dd033-1cc6-456d-8463-56eab8fea100', 'noticia', 'PagBank (verbete)', 'PagBank (antigo PagSeguro ) é uma instituição bancária brasileira que atua como meio de pagamento eletrônico  sendo uma das responsáveis pela captura, transmissão e liquidação financeira de transações com cartões de crédito e débito, tanto no meio físico (com suas máquinas sem aluguel), quanto no meio eletrônico (com suas soluções de pagamento on-line),  sendo o braço mais rentável do grupo UOL .', 'https://pt.wikipedia.org/wiki/PagSeguro'),
('734dd033-1cc6-456d-8463-56eab8fea100', 'site_institucional', 'PagBank: Maquininhas, Investimentos e muito mais', 'PagBank: Maquininhas, Investimentos e muito mais X Com PagBank, seu negócio vende mais O banco especialista em brasileiros tem tudo para você vender como quiser: Maquininhas, Tap On e Link de Pagamentos. Peça já Maquininhas de Cartão PagBank: Aqui o dinheiro das vendas cai na hora. Conheça os planos Para vender com maquininha Para vender com maquininha Recomendado Super Max Vendas acima de R$2.000/mês Débito 0,58% Crédito 0,58% Crédito 6x 6,98% Crédito 12x 7,98% Taxas promocionais válidas por 30 dias ou até vender R$ 5.000 Débito 1,44% Crédito 3,49% Crédito 6x 10,88% Crédito 12x 13,78% Saiba mais Essencial Sem mínimo de vendas Débito 0% Crédito 0% QR Code Pix 0% Taxas promocionais válidas por 30 dias ou até vender R$ 1.500 Débito 2,39% Crédito 4,99% Crédito 6x 15,27% Crédito 12x 22,59% Saiba mais Para vender pelo celular Para vender pelo celular Tap On Maquininha grátis no celular Débito 0,88% Crédito 3,14% Crédito 6x 9,48% Crédito 12x 13,74% Saiba mais Link de Pagamento Venda pelo Whatsapp e receba na hora Pix 0% Crédito 0% Crédito 6x 9,48% Crédito 12x 13,74% Taxas promocionais válidas por 30 dias ou até vender R$ 5.000 Crédito 4,20% Crédito 6x 13,88% Crédito 12x 21,20% Saiba mais Confira planos exclusivos para quem fatura acima de R$ 5.000. Saiba mais Maquininhas do Plano Super Max: Moderninha ProFit R$ 871,64 12x de R$ 6,99 R$ 83,88 à vista Peça já Pagamento por aproximação Conexão Wi-Fi e Chip Minizinha NFC 2 R$ 118,80 12x de R$ 1,25 R$ 15,00 à vista Peça já Precisa de celular Pagamento por aproximação Moderninha Smart 2 R$ 838,80 12x de R$ 16,34 R$ 196,08 à vista Peça já Controle de estoque Gestão completa Minizinha Chip 3 R$ 298,80 12x de R$ 3,99 R$ 47,88 à vista Peça já Pagamento por aproximação Conexão Wi-Fi e Chip Moderninha Plus 2 R$ 346,80 12x de R$ 4,99 R$ 5', 'https://pagbank.com.br'),
('734dd033-1cc6-456d-8463-56eab8fea100', 'blog', 'Home - Blog PagBank', 'Home - Blog PagBank Assine nossa newsletter Abra sua conta Novidades 01/09/2026 01/09/2026 Como vender sem maquininha de cartão no seu negócio: confira alternativas Resumo do texto Confira quais alternativas existem para passar cartão sem maquininha; Entenda quando vale a pena vender sem esse equipamento; Conheça as vantagens e os cuidados de aceitar cartão de forma digital; Saiba como escolher a opção ideal para o seu tipo de venda; Descubra como o PagBank ajuda você a receber pagamento com […] 01/09/2026 Empreendedorismo Como ganhar dinheiro com IA: o guia para começar do zero 01/09/2026 Segurança Celular roubado o que fazer? Veja como informar e proteger sua conta PagBank 01/09/2026 Liberdade Financeira 27 melhores livros sobre investimentos para cada perfil de investidor 01/09/2026 Liberdade Financeira Como economizar dinheiro no dia a dia: 15 dicas que funcionam Newsletter Receba conteúdos exclusivos em seu e-mail Inscreva-se em nossa newsletter preenchendo seu e-mail abaixo. Seu nome Seu principal e-mail Cadastrar Últimos posts', 'https://blog.pagbank.com.br/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('19423530-3cbb-4ec0-a4d7-68da3bbaee42', 'Buser', 'https://www.buser.com.br', null, 'São José dos Campos , São Paulo', 'A Buser é uma empresa brasileira que oferece um aplicativo para telefones celulares no qual é possível comprar passagens para diversas cidades brasileiras a preços mais baratos do que o valor base cobrado pelas empresas de viação tradicionais .  É conhecida como "Uber de ônibus".', 2017);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('19423530-3cbb-4ec0-a4d7-68da3bbaee42', 'noticia', 'Buser (verbete)', 'A Buser é uma empresa brasileira que oferece um aplicativo para telefones celulares no qual é possível comprar passagens para diversas cidades brasileiras a preços mais baratos do que o valor base cobrado pelas empresas de viação tradicionais .  É conhecida como "Uber de ônibus".', 'https://pt.wikipedia.org/wiki/Buser'),
('19423530-3cbb-4ec0-a4d7-68da3bbaee42', 'site_institucional', 'Viagens de ônibus com mais conforto pelo menor preço | Buser', 'Viagens de ônibus com mais conforto pelo menor preço | Buser Saindo de Indo para Data de ida Data de volta Buscar Ver mais destinos Aqui é sem letras miúdas. É só você vivendo o seu caminho. Mais seguro Empresas e motoristas treinados e certificados pela ANTT. Ônibus com tecnologias exclusivas, como câmeras de fadiga e telemetria (GPS) e suporte 24 horas em todos os nossos canais. Prático como deve ser Viajar com a praticidade de comprar pelo app, sem pegar filas. No Fretamento, dá até pra acompanhar o embarque em tempo real. Não dá pra viajar de outro jeito. Barato e com qualidade Viagens de ônibus por até menos da metade do preço das passagens de rodoviária. Diversas opções de destino com qualidade e preço justo! Na mídia Veja o que falam sobre a Buser Viajar de Buser é escolher o caminho certo. E não é a gente quem tá falando. Ver todas as notícias Buser lança rota que vai da capital paulista ao parque de diversões Hopi Hari 17 de julho de 2025 Buser investe em praticidade e segurança para ajudar os brasileiros a viajar mais 21 de maio de 2025 Viagens de ônibus mais baratas que a passagem da rodoviária Confira aqui nossas promoções e rotas com menores preços. QUERO PROMO Compre pelo Whatsapp Encontre a viagem ideal para você. Reserve agora Baixe o app da Buser É do app para a poltrona do ônibus: Sem burocracia e com segurança! Destinos mais procurados Ônibus para São Paulo Saindo de A partir de Rio de Janeiro R$ 81,90 Ribeirão Preto R$ 75,90 Belo Horizonte R$ 149,99 Campinas R$ 20,90 São José do Rio Preto R$ 90,00 Ver mais ônibus Ônibus para Rio de Janeiro Saindo de A partir de São Paulo R$ 91,57 Belo Horizonte R$ 96,90 Vitória R$ 93,90 Ribeirão Preto R$ 129,90 Uberlândia R$ 138,90 Ver mais ônibus Ônibus para Belo Horizonte Saindo de A partir de Rio de Janeiro R$ 76,', 'https://www.buser.com.br'),
('19423530-3cbb-4ec0-a4d7-68da3bbaee42', 'blog', 'Buser', 'Buser Pesquisar Destinos O que fazer em Capitólio MG: o guia completo pra quem ainda não foi Segurança Segurança e conforto em viagens de ônibus: como escolher uma empresa confiável? Releases Buser lança um game na campanha de 9 anos de aniversário Dicas Ônibus ou Avião: Qual Compensa Mais? Comparativo Completo Publicado por Luiza Guimarâes em setembro 1, 2026 A gente botou preço, tempo, conforto e segurança na mesa. Descubra quando o ônibus compensa mais que o avião (e quando não compensa). Leia mais... Dicas Passagem de ônibus para show: guia completo para viajar a festivais gastando menos em 2026 Publicado por Luiza Guimarães em agosto 27, 2026 2026 tá sendo um dos anos mais barulhentos da história recente do Brasil. Veja como viajar de ônibus para shows e festivais gastando menos. Leia mais... Dicas Viagem a trabalho: como sobreviver (e até curtir) sem virar refém da agenda Publicado por Luiza Guimarães em agosto 24, 2026 Senta aí que essa conversa é boa. Viagem a trabalho pode ser tanto um saco quanto uma das melhores partes do emprego. Depende muito de como você encara. Vim te dizer que dá pra ser legal. Leia mais... Dicas Mochilão econômico para estudante: dá pra viajar muito gastando pouco Publicado por Luiza Guimarães em agosto 21, 2026 Bora resolver uma crença que trava muita gente boa - a ideia de que viajar exige dinheiro sobrando. Mochilão não é sobre ter pouco, é sobre gastar certo. Leia mais... Dicas Passagem de Ônibus Saindo de Brasília e Goiânia: Conforto, Segurança e Preço Baixo Publicado por Luiza Guimarães em agosto 18, 2026 Tem viagem que começa bem antes do embarque. Começa na hora em que você começa a imaginar os dias no destino ideal e escolhe com quem vai viajar. Leia mais... Destinos O que fazer em Capitólio MG: o guia completo pra quem ainda n', 'https://blog.buser.com.br');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('c495733c-fa77-47c6-8fd3-038354e9f39c', 'Looqbox', 'https://www.looqbox.com', 'Data Analytics (Dados)', 'São Paulo, SP', 'Plataforma de BI que utiliza IA para transformar dados em insights acionáveis, facilitando a tomada de decisões em grandes empresas por meio de consultas em linguagem natural.', 2015);
