insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('8df73923-847e-4e84-a6e0-053fbfab0b33', 'Clarice.ai', 'https://clarice.ai', 'DeepTech', 'São Paulo, SP', 'Assistente de escrita baseada em IA, ajuda na criação de conteúdos originais e na revisão de textos, com foco no português do Brasil.', 2019);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('8df73923-847e-4e84-a6e0-053fbfab0b33', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'Clarice.ai (DeepTech): Assistente de escrita baseada em IA, ajuda na criação de conteúdos originais e na revisão de textos, com foco no português do Brasil.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('8df73923-847e-4e84-a6e0-053fbfab0b33', 'site_institucional', 'Clarice.ai: A Inteligência Artificial para Escritores!', 'Clarice.ai: A Inteligência Artificial para Escritores! Junte-se a mais de 400.000 usuários! Crie incríveis posts de blog 10x mais rápido com IA. A Clarice.ai revisa, edita e humaniza seus textos em português do Brasil — para você focar no que importa: criar. +50 templates disponíveis Treinado em Português do Brasil Revisão Humanizada Experimente agora Mencionada em: 📝 VISÃO GERAL Qual conteúdo incrível você deseja criar com a Clarice.ai? Pela primeira vez uma IA que gera textos automagicamente ao alcance dos seus dedos. Em português brasileiro ;) Artigos Mídias Sociais Anúncios E-mail Website Nunca mais sofra com o bloqueio do escritor Escreva artigos de blog otimizados para SEO 10 vezes mais rápido com a Clarice.ai. Gere ideias, títulos e parágrafos inteiros para artigos originais com base no tema que você quiser Escreva outros conteúdos longos, como e-mails de venda, e-books e muito mais em segundos A Clarice.ai é capaz de escrever de forma inteligente sobre quase todos os temas O conteúdo é sempre original, 100% livre de plágio Experimente grátis 📝 Como funciona A única inteligência artificial que escreve com dupla camada de revisão Esqueça textos robotizados e crie textos únicos, criativos e altamente persuasivos por meio de uma escrita humanizada. + Claro Aponta as frases longas e difíceis de entender. + Conciso Mostra as palavras que estão sobrando no texto. + Forte Destaca advérbios, gerúndios e outros diminuidores de impacto. + Original Indica clichês, frases feitas e redundâncias. ⭐️ BENEFÍCIOS DA CLARICE.AI Como a Clarice.ai pode ajudar nas suas criações Pare de gastar tanto tempo escrevendo artigos de blog, posts de mídia social e e-mails de vendas. Escreva textos e conteúdos que convertem A Clarice.ai é treinada para produzir textos de marketing de alta conv', 'https://clarice.ai'),
('8df73923-847e-4e84-a6e0-053fbfab0b33', 'blog', 'Clarice.ai | Blog', 'Clarice.ai | Blog Categorias Entrar Siga nossas redes sociais Em destaque 9 de setembro de 2025 5 min de leitura 3 erros de argumentação que enfraquecem seu texto (e como evitar) Como evitar repetições na escrita (sem perder clareza) 2 de set. de 2025 5 min Dicas de escrita Como deixar seu texto mais envolvente 26 de ago. de 2025 3 min Escrever como se fala: quando isso atrapalha (e como evitar) 21 de ago. de 2025 6 min Dicas de escrita Conjunto de regras gramaticais Gramática Regras para uso correto da língua Desvios de estilo Pontos de melhorias no seu texto Mais recentes Carregar mais Encontre a melhor versão do seu texto. Assine nossa newsletter e receba dicas infalíveis para escrever melhor Transforme sua experiência com a escrita. Escreva melhor agora mesmo com ajuda da Clarice.ai. Experimente agora', 'https://clarice.ai/blog');
