insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('633a5f8a-583b-4f3c-8417-af22e803aff2', 'Stalse', 'https://www.stalse.com', 'DeepTech', 'São Paulo, SP', 'Consultoria especializada em dados e tecnologia, estruturando grandes volumes de dados para gerar automações e construir indicadores.', 2021);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('633a5f8a-583b-4f3c-8417-af22e803aff2', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'Stalse (DeepTech): Consultoria especializada em dados e tecnologia, estruturando grandes volumes de dados para gerar automações e construir indicadores.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('633a5f8a-583b-4f3c-8417-af22e803aff2', 'site_institucional', 'Stalse', 'Stalse Toggle navigation menu O seu parceiro em FALE COM UM ESPECIALISTA CONHEÇA A STALSE Parceiros de confiança no mercado Soluções sob medida para o seu negócio O que fazemos para transformar dados em resultados Web Analytics Somos especialistas em Tagueamento de websites e aplicativos, garantindo que seus dados sejam precisos, organizados e prontos para análise a qualquer momento. Saiba Mais Business Intelligence & CRO Geramos inteligência por meio de dados, propondo insights relevantes que irão auxiliar no crescimento do seu negócio. Saiba Mais Data Science & AI Exploramos dados e criamos modelos de machine learning alinhados à estratégia do cliente. Nossas análises e previsões apoiam decisões estratégicas com inteligência artificial. Saiba Mais CRM Aprimoramos o CRM para personalizar interações e melhorar a segmentação. Com dados estruturados, aumentamos o engajamento e a fidelização dos clientes. Saiba Mais Engenharia de dados Criamos a infraestrutura para coletar, organizar e processar os seus dados, permitindo que seus relatórios sejam mais precisos. Saiba Mais Desenvolvimento Conectando dados à ação para resultados reais Saiba Mais Outsourcing de Profissionais Alocação rápida de especialistas para reforçar seu time com flexibilidade e foco em entregas. Saiba Mais Cloud Services Migração, gestão e otimização financeira da nuvem com segurança e eficiência. Saiba Mais Squad as a Service Time multidisciplinar sob demanda para acelerar projetos sem burocracia. Saiba Mais IMPACTO COMPROVADO EM NÚMEROS Resultados Reais que Impulsionam Negócios com Inteligência e Precisão Combinamos dados, automação e análise estratégica para gerar impacto mensurável, previsibilidade operacional e crescimento sustentável para empresas de diferentes segmentos. FALE COM UM ESPECIALISTA →', 'https://www.stalse.com'),
('633a5f8a-583b-4f3c-8417-af22e803aff2', 'blog', 'Stalse', 'Stalse Toggle navigation menu Tudo sobre dados, negócios,  tecnologia e inovação. Neste espaço, reunimos conteúdos originais sobre o que move a Stalse: inovação, ciência de dados, mercado e cultura organizacional. Um canal para compartilhar nossa expertise e contribuir com a evolução dos profissionais e empresas que, como nós, acreditam no poder da informação. Google I/O 2026: tudo que você precisa saber Como as novidades do Google I/O 2026 reconfiguram workforce planning, arquitetura de dados e estratégia de presença digital para as organizações Gustavo Rufino - 31 de maio de 2026 Ler artigo Anterior Proximo Fique por dentro Google I/O 2026: tudo que você precisa saber Como as novidades do Google I/O 2026 reconfiguram workforce planning, arquitetura de dados e estratégia de presença digital para as organizações Ler artigo → Data Lake, Data Warehouse ou Lakehouse: entenda a diferença entre as arquiteturas Cloud e uso ideal Por que a escolha entre data lake, data warehouse e lakehouse deixou de ser uma decisão técnica e passou a definir o custo, a velocidade e a confiabilidade de cada decisão de negócio nos próximos anos Ler artigo → O que é FDE (Forward Deployed Engineering) em IA e como funciona? Como o Forward Deployed Engineering acelera o ROI da IA e transforma projetos que emperram na produção em vantagem competitiva real Ler artigo → Google Workspace Enterprise: como os Connected Sheets e os conectores nativos eliminam gargalos e trazem eficiência corporativa Saiba por que a arquitetura analítica do Google Workspace Enterprise é a decisão mais rentável da stack corporativa Ler artigo → GA4 e BigQuery no Google Cloud: o primeiro passo para operações avançadas de BI e Data Science Entenda por que a exportação dos dados brutos do GA4 para o BigQuery resolve problema ', 'https://www.stalse.com/blog');
