insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('153dd8d6-b36f-4dbf-aec1-0ebeadad9399', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'Hablla (MarTech): Plataforma de marketing conversacional para personalizar a comunicação entre marcas e consumidores.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('153dd8d6-b36f-4dbf-aec1-0ebeadad9399', 'site_institucional', 'Hablla Marketing Conversacional, integração de sistemas e CRM', 'Hablla Marketing Conversacional, integração de sistemas e CRM Menu início sobre nós clientes cases de sucesso soluções omnichannel integrador CRM automação conversacional inteligência artificial fale conosco ajuda e materiais documentação eBooks novidades imprensa blog política de privacidade Fechar fale conosco login Menu início sobre nós clientes cases de sucesso soluções omnichannel integrador CRM automação conversacional inteligência artificial fale conosco ajuda e materiais documentação eBooks novidades imprensa blog política de privacidade Fechar fale conosco login Inteligência Conversacional com Agentes Autônomos de IA Transforme seu atendimento com automação, integração omnichannel e CRM inteligente. sobre nós Ferramenta de Marketing Conversacional Hablla está revolucionando a comunicação empresarial com sua plataforma que unifica omnichannel, CRM e integração em uma única ferramenta. Com automação de marketing conversacional e inteligência artificial, a Hablla proporciona economia de tempo, redução de custos e uma operação simplificada. Acreditamos que a comunicação eficiente é a chave para o sucesso dos negócios. Junte-se a nós e conquiste a excelência. 30 milhões de atendimentos 13.600 usuários ativos + 68 milhões de automações executadas + 285 milhões de mensagens trocadas Comunicação empresarial revolucionária com automação de marketing conversacional omnichannel com os principais canais de comunicação WhatsApp Empresarial e Multicanalidade Real Sistema de atendimento completo Oferecemos um sistema de atendimento completo para equipes de suporte, equipes comerciais e qualquer outra área da empresa. Transbordo de atendimento adaptável Permitimos o transbordo de atendimento, adaptando-se às configurações e necessidades específicas de cada cliente. Experiência', 'https://www.hablla.com'),
('153dd8d6-b36f-4dbf-aec1-0ebeadad9399', 'blog', 'Blog - Hablla', 'Blog - Hablla Menu início sobre nós clientes cases de sucesso soluções omnichannel integrador CRM automação conversacional inteligência artificial fale conosco ajuda e materiais documentação eBooks novidades imprensa blog política de privacidade Fechar fale conosco login Menu início sobre nós clientes cases de sucesso soluções omnichannel integrador CRM automação conversacional inteligência artificial fale conosco ajuda e materiais documentação eBooks novidades imprensa blog política de privacidade Fechar fale conosco login Hablla Blog Navegando no mundo da automação 21 de abril de 2026 Plataforma atendimento omnichannel vale a pena? marcusbarboza Nenhum comentário Entenda como uma plataforma atendimento omnichannel centraliza canais, dados e times para escalar vendas, suporte e produtividade. leia mais 17 de abril de 2026 CRM Corban: Como escalar operações de crédito consignado com automação e inteligência conversacional marcusbarboza Nenhum comentário O mercado de correspondentes bancários (Corban) opera sob alta pressão por produtividade, velocidade e conversão. A competição é intensa, os leads são disputados e o timing de atendimento define quem fecha ou perde a venda. Nesse cenário, operar sem um CRM estruturado não é apenas ineficiente — é um gargalo direto de receita. A questão […] leia mais 19 de fevereiro de 2026 Relationship Selling 2.0: Como vender pelo relacionamento escalou com IA marcusbarboza Nenhum comentário Vender pelo relacionamento nunca foi novidade. Desde os anos 1970, empresas B2B complexas já sabiam: quanto maior o risco percebido, maior a necessidade de confiança. E confiança se constrói com tempo, presença e memória. O problema nunca foi a teoria. Foi a escala. Um vendedor top consegue lembrar de tudo. Liga no aniversário do cliente. […] leia m', 'https://hablla.com/blog/');
