('decb7b52-759f-4b6f-bd4f-0fe55ca82225', 'Nuvia', 'https://www.nuvia.ai', 'SalesTech / IA conversacional para vendas B2B', 'São Paulo, SP', 'Plataforma de IA conversacional voltada a vendas B2B: agentes de IA centralizam prospecção, qualificação de leads, atendimento e fechamento em uma única tela, unificando canais, histórico e contexto do cliente para o time comercial.', 2024);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('decb7b52-759f-4b6f-bd4f-0fe55ca82225', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'Nuvia (MarTech): Oferece soluções para análise de dados de marketing, auxiliando empresas na tomada de decisões estratégicas.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('decb7b52-759f-4b6f-bd4f-0fe55ca82225', 'site_institucional', 'Nuvia - Todas as conversas com o cliente em uma única plataforma', 'Nuvia - Todas as conversas com o cliente em uma única plataforma Conversas 🇧🇷 BR Login Agendar Demo Todas as conversas com o cliente em uma única plataforma Prospecte, venda e atenda. Canais, histórico e contexto conectados, com agentes de IA e seu time na mesma tela Teste Agora Empresas que confiam na Nuvia Vector Vector Vector Vector Vector Vector Vector Vector Vector Vector Vector Vector agentes de ia Um agente de IA, múltiplas conversas. Funis inteligentes que conduzem cada conversa do atendimento à venda -aumentando a performance do time. Atendimento Resolve dúvidas em segundos Qualificação Separa o lead quente SDR / Prospecção Aborda e agenda reunião Suporte / Operações Abre e resolve chamados Crie seu agente indústrias Feita para o seu segmento Casos de uso reais do seu setor, do primeiro contato ao pós venda HealthTech HRTech Turismo Varejo SaaS Serviços Financeiros Automotivo Energia Educação HealthTech Dores Agendamentos e remarcações manuais Alto índice de no-show Dúvidas de pacientes fora do horário Triagem lenta de novos pacientes Gatilhos Agendamento e confirmação automáticos Lembretes que reduzem no-show Atendimento a pacientes 24/7 Qualificação e triagem inicial Crie seu Agente soluções Três soluções. Um objetivo Cobrimos toda a jornada de receita - do primeiro contato ao fechamento. Nuvia Conversas Resolve a maioria das conversas sozinho, em todos os canais. Caixa de entrada unificada (whatsapp, chat, e-mail, redes) Agentes de IA para atendimento 24/7 Roteamento inteligente por contexto Templates e respostas rápidas Relatórios de SLA e CSAT em tempo real Teste Agora Nuvia Prospecta Encontra contas com fit e abre a conversa por você Cadências em Whatsapp, e-mail e Linkedin SDR de IA para qualificação de follow-up Enriquecimento de leads automático Identi', 'https://www.nuvia.ai'),
('decb7b52-759f-4b6f-bd4f-0fe55ca82225', 'blog', 'Novidades da Nuvia | Nuvia', 'Novidades da Nuvia | Nuvia Conversas 🇧🇷 BR Login Agendar Demo Blog Novidades da Nuvia Guias, estratégias e novidades sobre vendas com IA — direto do time da Nuvia. Todos Guias Notícias Tecnologia de IA Produto Estratégia de Vendas Estratégia de Vendas 13 de abr. de 2026 Como Qualificar Leads com IA e Aumentar as Vendas B2B Descubra como a qualificação de leads com IA automatiza funis, aumenta a precisão e melhora a conversão em vendas B2B. Guias 7 de abr. de 2026 Omnichannel: integração de canais para aumentar vendas B2B Descubra como integrar canais físicos e digitais com CRM e IA para melhorar a jornada e aumentar vendas B2B. Estratégia de Vendas 12 de mar. de 2026 Nutrição e Follow-Up Inteligentes: Como a IA Cria Relacionamentos Que Convertem em Vendas B2B Nutrição e follow-up não são mais sobre mandar e-mails. Com IA e Data Intelligence, a Nuvia cria relacionamentos automatizados, personalizados e contínuos que aumentam conversão, reduzem CAC e tornam o funil previsível. Estratégia de Vendas 12 de mar. de 2026 Ferramentas e Estratégias de Prospecção & Verificação de E-mails/Leads: O Papel da IA e da Nuvia no Futuro do B2B Prospecção B2B eficaz depende de ferramentas que geram listas qualificadas, validam dados e automatizam processos. Veja as tendências de 2025, como IA transforma verificação de leads e por que a Nuvia lidera essa revolução com AI Agents ALLBOUND. Estratégia de Vendas 12 de mar. de 2026 Integração entre Marketing Digital e Vendas: Uso de Dados e Comunicação Personalizada para Aumentar Conversões Marketing e vendas precisam operar como um sistema único. A integração orientada por dados, IA e comunicação personalizada reduz desperdícios, melhora o funil e aumenta as taxas de conversão. Descubra como a Nuvia potencializa essa integração com AI Agents A', 'https://nuvia.ai/blog');
