('ac2a25ef-6b98-4d33-a0cd-5120082af225', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'Agendor (MarTech): Plataforma SaaS B2B voltada para vendas de relacionamento, com funcionalidades de CRM e automação de processos comerciais.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('ac2a25ef-6b98-4d33-a0cd-5120082af225', 'site_institucional', 'Agendor | Sistema CRM online para vendas consultivas B2B', 'Agendor | Sistema CRM online para vendas consultivas B2B Ir para o conteúdo principal Fazer login Criar conta grátis A era do vendedor preencher o CRM chegou ao fim O CRM que entende como o brasileiro vende. Comece já. É grátis Grátis pra sempre. Sem cartão de crédito. 4,8/5 em 5.856 avaliações Indústrias Distribuidoras Transportadoras Marcos · Metalúrgica Andrade online agora Fechado! Pode programar a entrega das 200 unidades pra março. 14:32 Perfeito, Marcos! Emito o pedido hoje e te mando o follow-up da recompra. 14:33 ✓✓ Agente de IA registrou no CRM a Willian Nakamura Chocolates do Sul… PRÉ FVD VEN PÓS REC Funil de Vendas $ R$ 393.411,93 42 negócios NEGOCIAÇÃO 7 · R$ 115.032,75 5110 – Metalúrgica Andrade Metalúrgica Andrade R$ 104.700,00 ✓ Ganho · agora 4642 – Loja Nova Sul Loja Nova Sul R$ 30,25 FECHAMENTO 8 · R$ 4.368,00 + de 10.000 empresas A jornada O Software CRM para vendas B2B, seja qual for o estágio da sua operação comercial Se você nunca usou um CRM. E quer sair da confusão das planilhas. Se seu time não preenche o CRM. Aqui, o CRM se completa sozinho Se você quer resultado previsível. O Agendor Intelligence te dá isso. Você não troca de ferramenta quando muda de momento. Só sobe de degrau. Comece do jeito mais simples que existe. A planilha funcionou até aqui. O Agendor é o passo seguinte: o CRM mais fácil de adotar do Brasil, grátis para sempre para até 3 usuários. Em uma semana, o time está usando, sem consultoria, sem manual, sem drama. Funil visual que qualquer vendedor entende no primeiro dia Importação da sua planilha em minutos App no celular, com mapa de clientes para quem vende na rua O que entra em jogo Funil de vendas Contatos e empresas Tarefas e agenda App iOS e Android Mapa de visitas Relatórios essenciais Criar conta grátis Plano gratuito ', 'https://www.agendor.com.br'),
('ac2a25ef-6b98-4d33-a0cd-5120082af225', 'blog', 'Portal de Artigos Práticos para Alta Performance em Vendas | Blog Agendor', 'Portal de Artigos Práticos para Alta Performance em Vendas | Blog Agendor Portal de Artigos Práticos para Alta Performance em Vendas Prospecção Somente 2,65% dominam a prospecção B2B: o Raio-X de 5.000 vendedores no Brasil Autor convidado Ver no LinkedIn Artigos populares Casos de sucesso Como a Garin Brasil centralizou informações e simplificou a jornada do cliente com o ecossistema Agendor Há quase cinco décadas no mercado brasileiro, a Garin Brasil construiu sua história unindo tradição, qualidade e inovação. Fundada como uma empresa familiar, a fabricante… Gustavo Gomes Processo comercial Panorama das Vendas Industriais 2026: o que separa as indústrias que crescem das que estão ficando para trás? Em um cenário de vendas mais complexo, ciclos longos, clientes postergando decisões e novas tecnologias surgindo a todo momento, o que explica por que algumas… Júlio Paulillo Processo comercial Como criar um Agente de IA SDR integrado ao Agendor Se você trabalha com vendas, sabe que um bom trabalho de SDR (ou pré-vendas) é essencial para que os vendedores abordem apenas os leads que… Autor convidado Listas de leitura Construindo um processo comercial VEJA MAIS » Fidelizando seus clientes VEJA MAIS » Guia completo de gestão e vendas para indústrias VEJA MAIS » Guia completo de vendas para distribuidoras VEJA MAIS » Guia: conteúdos essenciais para sucesso em logística VEJA MAIS » Identificando gargalos no processo comercial VEJA MAIS » Implementando um CRM VEJA MAIS » Negociando com os novos leads VEJA MAIS » Prospectando novas oportunidades VEJA MAIS » Artigos mais recentes Atendimento ao cliente , CRM , Gestão de clientes , Processo comercial Novo app do Agendor Chat: venda mais pelo WhatsApp no celular Seu vendedor está em uma visita quando chega uma mensagem de um cliente', 'https://www.agendor.com.br/blog/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('4c782bc0-922a-4c5e-a2f9-a161d7b18b33', 'O2Obots', 'https://www.o2obots.com', 'MarTech', 'Florianópolis, SC', 'Solução com IA para automatizar processos de vendas e atendimento, conectando empresas a clientes de forma eficiente.', 2017);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('4c782bc0-922a-4c5e-a2f9-a161d7b18b33', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'O2Obots (MarTech): Solução com IA para automatizar processos de vendas e atendimento, conectando empresas a clientes de forma eficiente.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('4c782bc0-922a-4c5e-a2f9-a161d7b18b33', 'site_institucional', 'O2OBOTS — Agentes de IA para o Ciclo de Crédito', 'O2OBOTS — Agentes de IA para o Ciclo de Crédito INFRAESTRUTURA DE IA PARA SERVIÇOS FINANCEIROS O sistema operacional para o ciclo de crédito. Agentes de IA Especializados em Serviços Financeiros A primeira inteligência artificial que domina o ciclo completo de crédito. Motor de vendas, cobrança e renegociação de dívidas, desenhado para escalar o balanço financeiro de bancos, seguradoras e fintechs. Fale com um especialista Volume de Originação +R$460M Em crédito e seguros distribuídos via inteligência artificial sem atrito humano. Caixa Previsível +R$50M Inadimplência rotineira (early stage) transformada em liquidez imediata via WhatsApp. Passivo Recuperado +R$10M De PDD e dívidas complexas recuperadas, blindando o seu balanço financeiro. Clientes e Parceiros A JORNADA COMPLETA DO DINHEIRO Um agente de IA para cada etapa do crédito Orquestramos todas as entradas e saídas do seu caixa. Em vez de fragmentar a sua operação em várias ferramentas, a nossa infraestrutura cobre 100% do ciclo de crédito. Da prospecção inicial à recuperação cirúrgica de passivos. Agente Especializado em Vendas de Serviços Financeiros Agente especializado em vendas de crédito consignado, seguros, consórcios, auto e home equity. Saque Aniversário FGTS Seguros Consórcios Consignado Privado Auto Equity Home Equity Veja a solução FASE 01: ORIGINAÇÃO E ONBOARDING. Motor de Vendas Autônomas Agente Especializado em Cobrança Automatizada Agente de cobrança que executa fluxos inteligentes com abordagem empática e alta taxa de ativação. Fluxo Preventivo (pré-vencimento) Ativação de Inadimplentes Conversas WhatsApp (texto e voz) Oferta de Parcelamento Conversas Humanizadas PIX Cobrança Inteligente Veja a solução FASE 02: PREVENÇÃO E RETENÇÃO. Sistema Inteligente de Cobrança Agente Especializado em Renegocia', 'https://www.o2obots.com'),
('4c782bc0-922a-4c5e-a2f9-a161d7b18b33', 'blog', 'Blog — O2OBOTS', 'Blog — O2OBOTS Blog e Insights Domine a Inovação em Crédito Estratégias avançadas de automação, recuperação e o impacto da IA no mercado financeiro. 🏆 Post em Destaque • 15 de out. Como Agentes de IA reduzem custos operacionais em Bancos e Fintechs A pressão por eficiência em Bancos e Fintechs é algo constante e um dos principais desafios é elevar produtividade e reduzir OPEX (despesas operacionais) sem travar o crescimento nem piorar a experiência do cliente. A boa notícia é que Agentes de IA já entregam valor quando aplicados a processos de alto volume e repetição, liberando equipes para atividades de maior impacto e acelerando time-to-mar… Ler o artigo completo Cobrança e Dívidas Cada dívida não cobrada é receita perdida. Cada dívida não cobrada corrói seu balanço. Modernize sua esteira de recuperação conectando suas políticas de risco à nossa mesa autônoma de renegociação. Fale com um especialista Últimos Artigos 66 Todos IA Vendas Cobrança Dívidas IA 15 de out. 5 min leitura Como Agentes de IA reduzem custos operacionais em Bancos e Fintechs Como a automação e a IA no WhatsApp estão transformando eficiência em crescimento no setor financeiro Image by Freepik A pressão por eficiência em Ban... Growth Team → Vendas 30 de set. 5 min leitura 5 Gargalos Operacionais que Agentes de IA já Estão Resolvendo no Setor Financeiro Do backlog à operação: como destravar produtividade, reduzir CAC e elevar conversão com IA no WhatsApp. Image by FreePik Uma pesquisa recente da IDC e... Growth Team → IA 25 de set. 5 min leitura A Era Agentic e o futuro dos negócios com Agentes de IA A nova fase da IA já começou: Agentes que executam e não apenas sugerem, capazes de conduzir fluxos ponta a ponta com impacto direto em receita, custo... Growth Team → IA 17 de set. 5 min leitura Panoram', 'https://www.o2obots.com/blog');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('d00187e2-7c27-4872-8034-b7677a305513', 'Post Sucesso', 'https://www.postsucesso.com.br', 'MarTech', null, 'Ferramenta de IA que gera conteúdo pronto para Instagram — carrosséis, stories e legendas adaptados ao nicho do usuário — permitindo criar e agendar posts em poucos cliques, sem produção manual de peças.', null);
insert into documentos (startup_id, tipo, titulo, conteudo_texto, url_fonte) values
('d00187e2-7c27-4872-8034-b7677a305513', 'noticia', 'Startups de IA: o que são e principais nomes no Brasil', 'Post Sucesso (MarTech): Ferramenta que otimiza postagens em redes sociais, analisando dados para maximizar o alcance e engajamento.', 'https://www.distrito.me/blog/startups-de-ia-o-que-sao-e-principais-nomes-no-brasil'),
('d00187e2-7c27-4872-8034-b7677a305513', 'site_institucional', 'Home - PostSucesso', 'Home - PostSucesso TESTE AGORA Finalmente uma IA que entende seu nicho e fala com o seu público. Carrosséis e stories que parecem feitos à mão, prontos em 5 minutos. TESTE AGORA Chega de posts genéricos que ninguém engaja. Parceiros: PostSucesso: conteúdo que vende, sem perder seu dia produzindo. Crie seus posts em 7 cliques. Chega de bloqueios criativos. Encontre ou crie imagens do seu nicho. Nossa IA cria ou pesquisa imagens por você. Um clique e seu post vai direto para o Canva. Faça edições em poucos cliques. Agende seus posts direto no PostSucesso. Seu Instagram no piloto automático. Postar no Insta todo dia tá difícil né, meu filho? 8:00 Você acorda e precisa postar algo (mas não sabe o que publicar). 8:30 Entre memes e fofocas, você scrolla o feed do Instagram por 30 minutos procurando ideias de conteúdo. 9:10 Surge uma ideia. Ótimo. 2 horas 3 horas 4 horas montando um post. 30 minutos escrevendo. 40 minutos procurando uma imagem descente. 20 minutos editando no Canva. 30 minutos procrastinando. Aí você termina, posta e… adivinha? 12 curtidas após meio dia de produção. Como é o dia de quem usa o PostSucesso? 8:00 — Você acorda e precisa postar algo. Com o PostSucesso, basta preencher quem é o seu público alvo e o assunto para nossa IA gerar ideias. Ou… Nossa IA pode gerar conteúdos com o modo inspiração, colocando um link de vídeo do YouTube ou texto autoral. 8:01 — O PostSucesso oferece temas com promessas relacionadas ao assunto que você deseja falar. 8:02 — Em poucos minutos você tem 10 opções de títulos matadores para o seu post. 8:03 — O texto do seu conteúdo está pronto. 8:03 — Com o texto pronto, você escolhe o estilo do seu carrossel (minimalista, narrativo ou stories). 8:04 — Após escolher o estilo do post, nossa IA direciona você na escolha (ou criação)', 'https://www.postsucesso.com.br'),
('d00187e2-7c27-4872-8034-b7677a305513', 'blog', 'Blog do PostSucesso - PostSucesso', 'Blog do PostSucesso - PostSucesso Ir para o conteúdo Blog do PostSucesso O algoritmo do Instagram explicado de forma simples Mauro Favoretto 24/04/2026 Leia Mais » O que é gestão de redes sociais? O guia completo Mauro Favoretto 17/04/2026 Leia Mais » Por que perfis pequenos estão crescendo mais rápido que grandes Mauro Favoretto 09/04/2026 Leia Mais » Como crescer no Instagram sem gastar com anúncios Mauro Favoretto 03/04/2026 Leia Mais » Como a Rede Social Pode Mudar a Vida do Microempreendedor? Mauro Favoretto 28/03/2026 Leia Mais » A Dopamina do feed: por que é tão difícil parar de rolar o Instagram? Mauro Favoretto 20/03/2026 Leia Mais » Psicologia do engajamento no Instagram: Mauro Favoretto 13/03/2026 Leia Mais » Como criar sua buyer persona para estratégias no Instagram Mauro Favoretto 06/03/2026 Leia Mais » O que é Story e como usar esse formato no Instagram? Mauro Favoretto 27/02/2026 Leia Mais » Como postar story no Instagram pelo PC: Mauro Favoretto 20/02/2026 Leia Mais » O que é retenção e por que ela importa no Instagram? Mauro Favoretto 12/02/2026 Leia Mais » O que significa POV no Instagram? Entenda essa tendência viral Mauro Favoretto 06/02/2026 Leia Mais » O que é DIX no Instagram e como ele funciona? Mauro Favoretto 29/01/2026 Leia Mais » Como descobrir o melhor dia para postar no Instagram Mauro Favoretto 23/01/2026 Leia Mais » Teste A/B: o segredo para descobrir o que funciona no Instagram Mauro Favoretto 16/01/2026 Leia Mais » Calendário Semanal Eficiente de Conteúdo no Instagram Mauro Favoretto 08/01/2026 Leia Mais » Infoproduto: como divulgar e vender pelo Instagram Mauro Favoretto 02/01/2026 Leia Mais » Retargeting no Instagram: o Segredo para Conversões Mais Altas Mauro Favoretto 26/12/2025 Leia Mais » Inspirações de case de sucesso para aplica', 'https://postsucesso.com.br/blog/');
insert into startups (id, nome, site, setor, localizacao, descricao_curta, ano_fundacao) values
('14772aa9-b457-4389-ba89-e0efc06ce15c', 'Monest', 'https://www.monest.com.br', 'FinTech', 'Curitiba, PR', 'Recuperação de ativos por meio da cobrança de débitos por uma agente virtual chamada Mia. A startup possui um sistema digital e inteligente que testa, aprende, entende e melhora as estratégias digitais de abordagem para com os devedores e possibilita que as empresas acompanhem em tempo real o desempenho da recuperação dessas dívidas.', 2018);
